mapper.select:
SELECT FINPROD_MARKET_ID code, case FINPROD_TYPE2 when #{FINPROD_TYPE_ZQ} then FINPROD_ABBR ELSE FINPROD_NAME end name, case FINPROD_TYPE2 when #{FINPROD_TYPE_ZQ} then FINPROD_ABBR ELSE FINPROD_NAME end shortName, FINPROD_MARKET_ID hidCode FROM FIN_PRODUCT
and (FINPROD_MARKET_ID like concat(concat('%',#{search}),'%') or FINPROD_NAME like concat(concat('%',#{search}),'%'))
AND FINPROD_TYPE in
#{item}
AND P_FINPROD_ID IS NULL
and PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}

SELECT MST_CUSTOMER_INFO.CUSTOMER_ID id, MST_CUSTOMER_INFO.CUSTOMER_NAME text,
MST_CUSTOMER_INFO_ADD.INSITITUTE_CODE col FROM MST_CUSTOMER_INFO LEFT JOIN MST_CUSTOMER_INFO_ADD ON MST_CUSTOMER_INFO.CUSTOMER_ID = MST_CUSTOMER_INFO_ADD.CUSTOMER_ID
where 1=1
and ( MST_CUSTOMER_INFO.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) OR MST_CUSTOMER_INFO.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{search}, '%')) OR MST_CUSTOMER_INFO.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) )
and ( MST_CUSTOMER_INFO.CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{initValue}, '%')) OR MST_CUSTOMER_INFO.CUSTOMER_ABBR LIKE CONCAT('%', CONCAT(#{initValue}, '%')) OR MST_CUSTOMER_INFO.CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{initValue}, '%')) )
/** modify by yanya on 20210323 去除是否管理人条件**/
AND MST_CUSTOMER_INFO.IS_TRUSTER = #{IS_TRUSTER}
AND MST_CUSTOMER_INFO.IS_FINANCIER = #{IS_FINANCIER}
AND MST_CUSTOMER_INFO.IS_GUARANTEE = #{IS_GUARANTEE}
AND MST_CUSTOMER_INFO.IS_INVEST_ADVISER = #{IS_INVEST_ADVISER}

SELECT CALENDAR_ID id, CALENDAR_NAME text FROM MST_CALENDAR_INFO
( CALENDAR_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR CALENDAR_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND CALENDAR_ID = #{initValue}

SELECT
A.ACCOUNTING_CLASS
FROM
FIN_PRODUCT_CLASS A
WHERE A.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}

	AND A.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}


	AND A.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


	AND A.BLN_AREA = #{blnArea,jdbcType=VARCHAR}


	AND A.ORG_CLASS = #{orgClass,jdbcType=VARCHAR}


	AND A.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}



		AND A.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}


AND ROWNUM = 1

SELECT
  T.TAX_CLASS
FROM (
  SELECT
     A.TAX_CLASS
  FROM
     FIN_PRODUCT_CLASS A
  WHERE
    A.FINPROD_TYPE =  #{finprodType,jdbcType=VARCHAR}

		AND A.ASSET_TYPE = #{assetType,jdbcType=VARCHAR}


		AND A.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


		AND A.BLN_AREA = #{blnArea,jdbcType=VARCHAR}


		AND A.ORG_CLASS = #{orgClass,jdbcType=VARCHAR}


		AND A.PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}



			AND A.TRM_FUND_TYPE = #{trmFundType,jdbcType=VARCHAR}


    GROUP BY A.TAX_CLASS
) T WHERE ROWNUM = 1
